import{_ as a,c as s,o,b1 as t}from"./chunks/framework.DB4pVXIt.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"nav/FaceBook/模板消息/02.常见问题.md","filePath":"nav/FaceBook/模板消息/02.常见问题.md","lastUpdated":1744656561000}'),r={name:"nav/FaceBook/模板消息/02.常见问题.md"};function p(n,e,c,l,h,i){return o(),s("div",null,e[0]||(e[0]=[t('<h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="如何加快模板的审核和批准流程-💡" tabindex="-1">如何加快模板的审核和批准流程？💡 <a class="header-anchor" href="#如何加快模板的审核和批准流程-💡" aria-label="Permalink to &quot;如何加快模板的审核和批准流程？💡&quot;">​</a></h3><p>以下是一些加快模板审核和批准流程的方法：</p><p>消息模板命名清晰明了。例如，使用 bus_ticket_details 而非 template_014。 提供明确说明，帮助您企业之外的审核人员更好地理解您的消息模板将如何使用。例如，针对被拒消息模板，在申诉中添加示例。</p><p><a href="https://www.facebook.com/business/help/766346674749731?ref=search_new_1" target="_blank" rel="noreferrer">加快模板的审核和批准流程官方文档</a></p><h3 id="whatsapp-api-发送文本消息限制-💡" tabindex="-1">WhatsApp api 发送文本消息限制 💡 <a class="header-anchor" href="#whatsapp-api-发送文本消息限制-💡" aria-label="Permalink to &quot;WhatsApp api 发送文本消息限制 💡&quot;">​</a></h3><p>WhatsApp API 发送文本消息时，<code>消息长度限制为 4096 个字符</code>。如果消息长度超过这个限制，将会无法发送出去</p><p><a href="https://developers.facebook.com/docs/whatsapp/api/messages/text" target="_blank" rel="noreferrer">WhatsApp api 发送文本消息限制官方文档 1</a></p><p><a href="https://developers.facebook.com/docs/whatsapp/on-premises/reference/messages#---2" target="_blank" rel="noreferrer">WhatsApp api 发送文本消息限制官方文档 2</a></p><h3 id="在未经授权的情况下通过-whatsapp-自动发送或批量发送消息" tabindex="-1">在未经授权的情况下通过 WhatsApp 自动发送或批量发送消息 <a class="header-anchor" href="#在未经授权的情况下通过-whatsapp-自动发送或批量发送消息" aria-label="Permalink to &quot;在未经授权的情况下通过 WhatsApp 自动发送或批量发送消息&quot;">​</a></h3><p><a href="https://faq.whatsapp.com/5957850900902049/?helpref=uf_share" target="_blank" rel="noreferrer">在未经授权的情况下通过 WhatsApp 自动发送或批量发送消息</a></p><p><strong>For example, an account that registered five minutes before attempting</strong><strong>to send 100 messages in 15 seconds is almost certain to be engaged in</strong><strong>abuse, as is an account that attempts to quickly create dozens of groups</strong><strong>or add thousands of users to a series of existing groups We ban these</strong><strong>accounts immediately and automatically In less-obvious situations, a new</strong><strong>account might message dozens of recipients who do not have the sender’s</strong><strong>account in their contacts This could be the beginning of a spam attack,</strong><strong>or it could be an innocent user simply telling their contacts about a new</strong><strong>phone number In these cases, we consider historical information (for</strong><strong>instance, how suspicious their registration was) in order to separate</strong><strong>abnormal — but innocuous — user behavior In sum, our detection systems</strong><strong>evaluate hundreds of factors to shut down abuse</strong></p><p>例如，一个在尝试前五分钟注册的帐户 在 15 秒内发送 100 条消息几乎肯定会被参与其中 滥用，这是一个试图快速创建数十个群组的帐户 或将数千名用户添加到一系列现有组中我们禁止这些 在不太明显的情况下，新的 帐户可能会向数十个没有发件人信息的收件人发送邮件 这可能是垃圾邮件攻击的开始， 或者，它可能是一个无辜的用户，只是简单地告诉他们的联系人一个新的 电话号码在这些情况下，我们考虑历史信息（ 例如，他们的注册有多可疑），以便分开 异常但无害的用户行为总之，我们的检测系统 评估数百个因素以制止滥用</p><p>此外，自 2019 年 12 月 7 日起，如果我们确定有人参与或协助他人进行违反我们服务条款的滥用行为，例如<code>自动发送或批量发送消息，或将 WhatsApp 用于非个人用途</code>，即使 WhatsApp 所作的判定是完全基于在我们平台以外所获得的信息，我们也将对其采取法律措施</p><h3 id="api-消息类型" tabindex="-1">Api 消息类型 <a class="header-anchor" href="#api-消息类型" aria-label="Permalink to &quot;Api 消息类型&quot;">​</a></h3><p>我们支持两类消息：自由格式的消息(普通消息)和模板消息。模板消息只能向以下用户发送：已订阅允许企业向用户自己发送消息这一功能的用户。使用模板消息时，您必须使用模板，并且模板必须经过审核团队审核，这样才能向客户发送消息。<a href="https://developers.facebook.com/docs/whatsapp/overview/messages" target="_blank" rel="noreferrer">详细了解</a>。<a href="https://developers.facebook.com/docs/whatsapp/overview#---2" target="_blank" rel="noreferrer">官方消息文档说明</a></p><p><a href="https://developers.facebook.com/docs/whatsapp/conversation-types#faq_715120295540784" target="_blank" rel="noreferrer">如果我需要在客户联系我 24 小时后发送客户服务回复消息，怎么办？</a></p><h3 id="号码注册问题" tabindex="-1">号码注册问题 <a class="header-anchor" href="#号码注册问题" aria-label="Permalink to &quot;号码注册问题&quot;">​</a></h3><p>已经注册 WhatsApp api 号码无法注册 WhatsApp Messenger 应用或 WhatsApp Business 应用已使用的号码，除非先删除这些号码。如果您要删除号码，请参阅我们帮助中心的<a href="https://faq.whatsapp.com/2138577903196467/" target="_blank" rel="noreferrer">如何删除帐号</a>一文。</p><p>无法注册被封号的 WhatsApp 号码，除非先解封。如果帐号被封号，而您想提出申诉，<a href="https://developers.facebook.com/docs/whatsapp/support" target="_blank" rel="noreferrer">请联系支持团队</a>。</p><p><a href="https://developers.facebook.com/docs/whatsapp/cloud-api/phone-numbers#--" target="_blank" rel="noreferrer">官方文档说明</a></p><h3 id="注册电话号码数量限制-💡" tabindex="-1">注册电话号码数量限制 💡 <a class="header-anchor" href="#注册电话号码数量限制-💡" aria-label="Permalink to &quot;注册电话号码数量限制 💡&quot;">​</a></h3><p>一个 Facebook 可以绑定多少个 api 号码？</p><ul><li>您可创建最多 2 个业务资产组合。<strong>注意</strong>：这并不是对您可以加入的资产组合数量的限制<span style="background:#FFFFFF;color:#FF0000;"><a href="https://www.facebook.com/business/help/1710077379203657?id=180505742745347" target="_blank" rel="noreferrer">官方文档说明</a></span></li><li>业务资产组合最初仅限注册 2 个公司电话号码，但此上限可提高至 20。<span style="background:#FFFFFF;color:#FF0000;"><a href="https://developers.facebook.com/docs/whatsapp/cloud-api/phone-numbers#----------" target="_blank" rel="noreferrer">注册电话号码数量限制官方文档</a></span></li></ul><h3 id="whatsapp-business-商业帐号" tabindex="-1">WhatsApp Business 商业帐号 <a class="header-anchor" href="#whatsapp-business-商业帐号" aria-label="Permalink to &quot;WhatsApp Business 商业帐号&quot;">​</a></h3><h3 id="whatsapp-business-商业帐号可以拥有多少个模板数量-官方文档说明" tabindex="-1">WhatsApp Business 商业帐号可以拥有多少个模板数量？<span style="background:#FFFFFF;color:#FF0000;"><a href="https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#-------" target="_blank" rel="noreferrer">官方文档说明</a></span> <a class="header-anchor" href="#whatsapp-business-商业帐号可以拥有多少个模板数量-官方文档说明" aria-label="Permalink to &quot;WhatsApp Business 商业帐号可以拥有多少个模板数量？&lt;span style=&quot;background:#FFFFFF; color:#FF0000;&quot;&gt;[官方文档说明](https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#-------)&lt;/span&gt;&quot;">​</a></h3><p>WhatsApp Business 商业帐号可以拥有的模板数量由该帐号的母公司决定。如果母公司未经认证，则其下每个 WhatsApp Business 商业帐号最多可拥有 250 个模板。但是，如果母公司<a href="https://www.facebook.com/business/help/1095661473946872" target="_blank" rel="noreferrer">已经过认证</a>，且至少有一个 WhatsApp Business 业务账户具有商业电话号码和经批准的<a href="https://www.facebook.com/business/help/338047025165344" target="_blank" rel="noreferrer">显示名</a>，则每个 WhatsApp Business 业务账户最多可拥有 6,000 个模板。</p><h3 id="消息模板限制官方文档说明" tabindex="-1">消息模板限制<span style="background:#FFFFFF;color:#FF0000;"><a href="https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#--" target="_blank" rel="noreferrer">官方文档说明</a></span> <a class="header-anchor" href="#消息模板限制官方文档说明" aria-label="Permalink to &quot;消息模板限制&lt;span style=&quot;background:#FFFFFF; color:#FF0000;&quot;&gt;[官方文档说明](https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#--)&lt;/span&gt;&quot;">​</a></h3><ul><li><code>消息模板名称</code>字段的限制为 <code>512</code> 个字符。</li><li><code>消息模板内容</code>字段的限制为 <code>1,024</code> 个字符。</li><li>只有当模板处于<strong>已批准</strong>、<strong>未通过</strong>或<strong>已暂停</strong>状态时，才能对其进行编辑。您每天可以编辑模板<code>一次</code>，每个月最多可以编辑 <code>10 次</code>。</li><li>每个 WhatsApp Business 商业帐号<code>每小时只能创建 100 个消息模板</code>。</li><li>包含 <code>4 个或以上按钮</code>的模板或包含 <code>1 个快速回复按钮和 1 个或多个其他类型按钮</code>的模板无法在 WhatsApp 桌面版客户端上查看。如果 WhatsApp 用户收到一条包含此类模板的消息，系统会提示他们改用手机查看该消息。</li></ul><h3 id="我的送达率为什么不是-100" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/on-premises/reference/messages#faq_550341502008168" target="_blank" rel="noreferrer">我的送达率为什么不是 100%？</a> <a class="header-anchor" href="#我的送达率为什么不是-100" aria-label="Permalink to &quot;[我的送达率为什么不是 100%？](https://developers.facebook.com/docs/whatsapp/on-premises/reference/messages#faq_550341502008168)&quot;">​</a></h3><p><strong>注意：</strong> <code>请勿使用 WhatsApp Business API 向同一位收信人重复发送相同消息。</code></p><p>送达率不是 100% 可能有很多原因。其中一些常见情况包括：用户的网络断断续续、用户在一段时间内没有任何活动，或为建立 <a href="https://developers.facebook.com/docs/whatsapp/message-templates/creation#per-user-marketing-template-message-limits" target="_blank" rel="noreferrer">优质用户体验</a>。</p><p><em>可以</em>通过 WhatsApp 送达的消息<em>会</em>有非常高的送达率。但也存在很多原因可能导致消息送达失败。您可以通过监控回调，了解消息的确切状态。这与通过短信发送消息不同，例如，对于短信，您<em>无法</em>访问最终的送达状态，而再次发送消息<em>可能</em>确实会产生不同的成效。</p><p>消息未能成功送达的原因可能是用户的手机停机、没电，或者用户的手机遗失，并在更换新手机时弃用了 SIM 卡。也有可能是公司的客户端出错，因而无法连接到网络，或者是因为回调 (Webhook) 没有送达。您可使用 <code>health</code> 节点监控这些状况。您可以开启服务器接收回调，以便在消息进入 WhatsApp 服务器云时收到通知。</p><p>当用户重新连接到网络时，您之前发送的所有消息都会送达给用户。对用户而言，收到多条内容相同的消息会是非常糟糕的体验。因此，用户很可能会将您拉黑或者投诉您。您可能会遭到禁言。</p><p>如果您在发送消息后收到 API 发送的消息 ID，则说明您已经完成对此消息的发送。请勿向同一个收信人重复发送相同内容。</p><p>如果您发现送达率长期偏低，请提交支持工单至 <a href="https://developers.facebook.com/docs/whatsapp/support" target="_blank" rel="noreferrer">站内支持</a>。</p><h3 id="消息未送达" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/cloud-api/support#------2" target="_blank" rel="noreferrer"><code>消息未送达</code></a> <a class="header-anchor" href="#消息未送达" aria-label="Permalink to &quot;[`消息未送达`](https://developers.facebook.com/docs/whatsapp/cloud-api/support#------2)&quot;">​</a></h3><p>以下情景可能导致消息显示为“已发送”，而非“已送达”。出现这种情况的原因有很多，出于隐私和政策方面的考虑，<code>我们不会披露该错误的根本原因。</code></p><ul><li><p>在我们为离线客户保留消息的 30 天期限内，客户未曾上线。</p></li><li><p>客户已封锁此 WhatsApp Business 电话号码，或此商家拥有的其他 WhatsApp Business 电话号码。</p></li><li><p>客户位于<a href="https://developers.facebook.com/docs/whatsapp/cloud-api/support#-------" target="_blank" rel="noreferrer">受限或遭受制裁的国家/地区</a>。</p><h4 id="可行的解决方案" tabindex="-1">可行的解决方案 <a class="header-anchor" href="#可行的解决方案" aria-label="Permalink to &quot;可行的解决方案&quot;">​</a></h4><p>使用非 WhatsApp 联系方式，请 WhatsApp 用户执行以下操作：</p><ul><li>确认他们实际可以向您的 WhatsApp Business 电话号码发送消息</li><li>确认您的所有 WhatsApp Business 电话号码都不在他们的已封锁号码清单中（<strong>设置</strong> &gt; <strong>隐私</strong> &gt; <strong>已封锁</strong>或<strong>封锁的联系人</strong>）</li><li>确认他们已接受我们的最新服务条款（如果他们还未接受，在<strong>设置</strong> &gt; <strong>帮助</strong>中，或在<strong>设置</strong> &gt; <strong>应用程序信息</strong>中，系统会提示他们接受最新的条款或政策）</li><li>更新到最新版 WhatsApp 客户端</li></ul></li></ul><h3 id="消息可在-whatsapp-中存留多久" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/on-premises/reference/messages#faq_1536348526473805" target="_blank" rel="noreferrer"><code>消息可在 WhatsApp 中存留多久？</code></a> <a class="header-anchor" href="#消息可在-whatsapp-中存留多久" aria-label="Permalink to &quot;[`消息可在 WhatsApp 中存留多久？`](https://developers.facebook.com/docs/whatsapp/on-premises/reference/messages#faq_1536348526473805)&quot;">​</a></h3><p>在发送消息时，只要您获得了消息编号，便意味着系统已将该消息请求存储在数据库中。WhatsApp Business API 客户端会不断尝试发送该消息，直至收到 WhatsApp 服务器的确认为止。这一过程没有结束期限。然后 WhatsApp 服务器会尝试将该消息发送至用户的手机。如果用户的手机不在线，则消息将在 WhatsApp 服务器中存储 30 天，然后失效。</p><h3 id="如何获知用户是否已屏蔽我的公司" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/on-premises/reference/messages#faq_1874919319191147" target="_blank" rel="noreferrer">如何获知用户是否已屏蔽我的公司？</a> <a class="header-anchor" href="#如何获知用户是否已屏蔽我的公司" aria-label="Permalink to &quot;[如何获知用户是否已屏蔽我的公司？](https://developers.facebook.com/docs/whatsapp/on-premises/reference/messages#faq_1874919319191147)&quot;">​</a></h3><p>目前，您无法知道有多少用户，或者哪些用户已屏蔽您的公司。获知这一信息的最佳方法是侦听回调状态，如果您未收到 <code>delivered</code> 状态，则表明用户已屏蔽贵公司，或者用户未连接到网络。详情请参阅 <a href="https://developers.facebook.com/docs/whatsapp/webhooks" target="_blank" rel="noreferrer">Webhook</a> 文档。</p><p>如果用户已屏蔽贵公司，联系人 API 会继续返回“该手机号是有效的 WhatsApp 用户”这一消息。然而，在您发送消息时，系统永远不会将其传送出去。如果是付费消息，则您无需付费。</p><h3 id="系统能否保证按顺序发送消息" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/on-premises/reference/messages#faq_173242556636267" target="_blank" rel="noreferrer">系统能否保证按顺序发送消息？</a> <a class="header-anchor" href="#系统能否保证按顺序发送消息" aria-label="Permalink to &quot;[系统能否保证按顺序发送消息？](https://developers.facebook.com/docs/whatsapp/on-premises/reference/messages#faq_173242556636267)&quot;">​</a></h3><p>不能，我们无法保证消息的接收顺序与发送顺序相同。如果排序对您的用例十分重要，我们建议您在侦听到第一条消息的已发送回调后，再触发第二条消息。</p><h3 id="如果我需要在客户联系我-24-小时后发送客户服务回复消息-怎么办" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/on-premises/reference/messages#faq_715120295540784" target="_blank" rel="noreferrer">如果我需要在客户联系我 24 小时后发送客户服务回复消息，怎么办？</a> <a class="header-anchor" href="#如果我需要在客户联系我-24-小时后发送客户服务回复消息-怎么办" aria-label="Permalink to &quot;[如果我需要在客户联系我 24 小时后发送客户服务回复消息，怎么办？](https://developers.facebook.com/docs/whatsapp/on-premises/reference/messages#faq_715120295540784)&quot;">​</a></h3><p>在某些情况下，您可能需要更多时间来处理消费者查询，或者您只能在 24 小时后回复消息。我们建议您创建消息模板，以：</p><ul><li>将结果发送给用户，或</li><li>提醒用户回复以开启客户服务窗口。</li></ul><p>在这两种情况中，请务必为消息模板提供尽可能多的上下文。例如：</p><ul><li>“1，您好，关于您之前报告的问题，我们很遗憾地通知您 2。对于给您带来的任何不便，我们深表歉意。”</li><li>我们已更新您的请求单。如果您想继续获得支持服务，请回复。”</li></ul><h3 id="编辑模板限制" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#---3" target="_blank" rel="noreferrer"><code>编辑模板限制</code></a> <a class="header-anchor" href="#编辑模板限制" aria-label="Permalink to &quot;[`编辑模板限制`](https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#---3)&quot;">​</a></h3><ul><li>仅可编辑带有 <code>APPROVED</code>、<code>REJECTED</code> 或 <code>PAUSED</code> 状态的模板。 <a href="https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#---2" target="_blank" rel="noreferrer">有关模板状态参考官方文档</a></li><li>您仅可编辑模板的 <code>category</code> (模板类别)或 <code>components</code>(模板组件：模板由四个主要组件组成，这些组件是您在创建模板时定义的：页眉、正文、页脚和按钮)。</li><li><code>您无法编辑已批准模板</code>的 <code>category</code>(模板类别)。</li><li>您在连续 30 天内至多可以编辑 10 次处于已批准状态的模板（或每 24 小时编辑 1 次），对处于被拒或已暂停状态的模板的编辑次数则不受限制。</li><li>在您编辑处于已批准或已暂停状态的模板后，系统会自动批准该模板，除非该模板未通过模板审核。</li></ul><h3 id="不同模板类别定价为什么不一样" tabindex="-1">不同模板类别定价为什么不一样？ <a class="header-anchor" href="#不同模板类别定价为什么不一样" aria-label="Permalink to &quot;不同模板类别定价为什么不一样？&quot;">​</a></h3><p>类别会影响定价,详情查看官方文档说明：<a href="https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#template-categories" target="_blank" rel="noreferrer">https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#template-categories</a></p><h3 id="商业帐号类型" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/overview/business-accounts#types" target="_blank" rel="noreferrer">商业帐号类型</a> <a class="header-anchor" href="#商业帐号类型" aria-label="Permalink to &quot;[商业帐号类型](https://developers.facebook.com/docs/whatsapp/overview/business-accounts#types)&quot;">​</a></h3><table tabindex="0"><thead><tr><th><strong>名称</strong></th><th><strong>描述</strong></th></tr></thead><tbody><tr><td><strong>商业帐号</strong>(绿标)</td><td>默认情况下，使用 WhatsApp Business 开放平台或 <a href="https://business.whatsapp.com/products/business-app/" target="_blank" rel="noreferrer">WhatsApp Business 应用</a>的任何帐号都是商业帐号。<br>WhatsApp 会验证 WhatsApp Business 开放平台上每个帐号所属品牌的真实性。如果帐号已完成公司验证，即使用户未在通讯录中添加此公司，也能看到该公司的名称。</td></tr><tr><td><strong>官方商业帐号</strong>（蓝标）</td><td>官方商业帐号的商业简介以及聊天对话标题中会显示一个蓝色勾选标记徽章。详情请参阅<a href="https://developers.facebook.com/docs/whatsapp/overview/business-accounts#official-business-account" target="_blank" rel="noreferrer">官方商业帐号</a>。</td></tr></tbody></table><h3 id="申请官方商业帐号蓝标流程" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/overview/business-accounts#official" target="_blank" rel="noreferrer">申请官方商业帐号蓝标流程</a> <a class="header-anchor" href="#申请官方商业帐号蓝标流程" aria-label="Permalink to &quot;[申请官方商业帐号蓝标流程](https://developers.facebook.com/docs/whatsapp/overview/business-accounts#official)&quot;">​</a></h3><p>详情查看官方文档：<a href="https://developers.facebook.com/docs/whatsapp/overview/business-accounts#official" target="_blank" rel="noreferrer">https://developers.facebook.com/docs/whatsapp/overview/business-accounts#official</a></p><h3 id="查看是否符号公司验证资格" tabindex="-1">查看是否符号公司验证资格 <a class="header-anchor" href="#查看是否符号公司验证资格" aria-label="Permalink to &quot;查看是否符号公司验证资格&quot;">​</a></h3><p>前往商务管理平台的<a href="https://business.facebook.com/settings/security" target="_blank" rel="noreferrer">安全中心</a>就可以看到是否符合资格，如图</p><p><img src="https://assets-cdn.salesmartly.com/prod/project/fj3mnx/chat/plugin/image/20250118/1737176448627/image_1737176448627_d2b5ca33bd970f64a6301fa75ae.png" alt="安全中心"></p><p>如果显示<strong>不符合验证资格</strong>说明您 fb 个号有异常，详情查看<a href="https://www.facebook.com/business-support-home/?landing_page=overview&amp;source=actor_contact_form_misc" target="_blank" rel="noreferrer"><code>账号概览</code></a><img src="https://assets-cdn.salesmartly.com/prod/project/fj3mnx/chat/plugin/image/20250118/1737176310556/image_1737176310556_d2b5ca33bd970f64a6301fa75ae.png" alt="账号概览"><img src="https://assets-cdn.salesmartly.com/prod/project/fj3mnx/chat/plugin/image/20250118/1737176632506/image_1737176632506_d2b5ca33bd970f64a6301fa75ae.png" alt="账号概览"></p><h3 id="消息媒体类型大小限制" tabindex="-1">消息媒体类型大小限制 <a class="header-anchor" href="#消息媒体类型大小限制" aria-label="Permalink to &quot;消息媒体类型大小限制&quot;">​</a></h3><ul><li><code>WhatsApp Api</code> :<a href="https://developers.facebook.com/docs/whatsapp/on-premises/reference/media#supported-files" target="_blank" rel="noreferrer">媒体类型</a>：<a href="https://developers.facebook.com/docs/whatsapp/on-premises/reference/media#supported-files" target="_blank" rel="noreferrer">https://developers.facebook.com/docs/whatsapp/on-premises/reference/media#supported-files</a></li></ul><p><a href="https://developers.facebook.com/docs/whatsapp/cloud-api/guides/send-messages#-----2" target="_blank" rel="noreferrer">api 号码消息类型</a>：<a href="https://developers.facebook.com/docs/whatsapp/cloud-api/guides/send-messages#-----2" target="_blank" rel="noreferrer">https://developers.facebook.com/docs/whatsapp/cloud-api/guides/send-messages#-----2</a></p><p>云端 api 支持的媒体类型:<a href="https://developers.facebook.com/docs/whatsapp/cloud-api/reference/media#supported-media-types" target="_blank" rel="noreferrer">https://developers.facebook.com/docs/whatsapp/cloud-api/reference/media#supported-media-types</a></p><ul><li><code>Messager</code> 媒体附件上传大小：<a href="https://developers.facebook.com/docs/messenger-platform/reference/attachment-upload-api#attachment" target="_blank" rel="noreferrer">https://developers.facebook.com/docs/messenger-platform/reference/attachment-upload-api#attachment</a></li></ul>',69)]))}const m=a(r,[["render",p]]);export{f as __pageData,m as default};
